/// <summary>
/// The <c>AVAContainerLabelPrintIDisposable</c> represents a iDisposable interface for container label print
/// </summary>
/// <remarks>
/// AVA_7303_9393_ContainerLabelOnClose
/// </remarks>
class AVAContainerLabelPrintIDisposable  implements System.IDisposable
{
    public boolean   showDialog;

    static AVAContainerLabelPrintIDisposable instance;

}

Method.Source:
protected void new()
{
    if (!AVAContainerLabelPrintIDisposable::current())
    {
        instance = this;
    }
    else
    {
        instance = AVAContainerLabelPrintIDisposable::current();
    }
}

/// <summary>
/// AVA_7303_9393_ContainerLabelOnClose
/// </summary>
/// <returns>
/// Current instance of <c>AVACloseContainerUsingParamIDisposable</c>
/// </returns>
/// <remarks>
/// AVA_7303_9393_ContainerLabelOnClose
/// </remarks>
public static AVAContainerLabelPrintIDisposable current()
{
    return instance;
}

public static AVAContainerLabelPrintIDisposable construct()
{
    return new AVAContainerLabelPrintIDisposable();
}
